selected':'' ?>>Archived (authorized managers)</option></select></div><div class="client-actions"><button type="submit" class="btn btn-teal">Apply filters</button><a class="btn btn-outline-light" href="<?= site_url('tasks') ?>">Reset</a></div></form>
